    def test_group_call_destination_internal_is_answering_callee(self):
        other_member_uuid = '64f7ec70-71b7-4430-8446-74d8dc563d33'
        answer_member_uuid = '203bcf07-d355-44e8-8217-f6f532737bf1'
        self.confd.set_users(
            MockUser(other_member_uuid, USERS_TENANT, line_ids=[1]),
            MockUser(answer_member_uuid, USERS_TENANT, line_ids=[2]),
        )
        self.confd.set_lines(
            MockLine(
                id=1,
                name='uzyebgp2',
                users=[{'uuid': other_member_uuid}],
                tenant_uuid=USERS_TENANT,
                extensions=[{'exten': '1204', 'context': 'internal'}],
            ),
            MockLine(
                id=2,
                name='4kr6r6tu',
                users=[{'uuid': answer_member_uuid}],
                tenant_uuid=USERS_TENANT,
                extensions=[{'exten': '1201', 'context': 'internal'}],
            ),
        )
        self.confd.set_contexts(
            MockContext(id=1, name='internal', tenant_uuid=USERS_TENANT)
        )

        self._assert_last_call_log_matches(
            '1775582519.345',
            has_properties(
                source_name='User Caller',
                source_exten='1001',
                requested_exten='2002',
                destination_internal_exten='1201',
                destination_internal_context='internal',
                destination_name='group2',
                destination_participant=has_properties(
                    user_uuid=UUID(answer_member_uuid),
                ),
            ),
        )

