    def test_group_call_answered_by_mobile_names_group_and_answering_member(self):
        # the answering channel's caller ID does not name its user: confd does
        tenant_uuid = '47bfdafc-2897-4369-8fb3-153d41fb835d'
        answer_member_uuid = '47378190-96da-4dac-b2ff-5d2a386ecbe0'
        other_member_uuid = '1a2a73ed-562b-4f79-8374-59eef50bea63'
        context = 'ctx-ID00000001-internal-0e51f30d-c6a7-4e39-84b0-32ccd7c524a5'
        self.confd.set_users(
            MockUser(
                answer_member_uuid,
                tenant_uuid,
                line_ids=[1],
                firstname='Group',
                lastname='Member',
            ),
            MockUser(
                other_member_uuid,
                tenant_uuid,
                line_ids=[2],
                firstname='Ringing',
                lastname='Member',
            ),
        )
        self.confd.set_lines(
            MockLine(
                id=1,
                name='msn9dLVI',
                users=[{'uuid': answer_member_uuid}],
                tenant_uuid=tenant_uuid,
                extensions=[{'exten': '200', 'context': context}],
            ),
            MockLine(
                id=2,
                name='9UYJQTFj',
                users=[{'uuid': other_member_uuid}],
                tenant_uuid=tenant_uuid,
                extensions=[{'exten': '201', 'context': context}],
            ),
        )
        self.confd.set_contexts(
            MockContext(id=1, name=context, tenant_uuid=tenant_uuid)
        )

        self._assert_last_call_log_matches(
            '1793630284.0',
            has_properties(
                requested_name='default_group',
                destination_name='Group Member',
                destination_internal_exten='200',
                destination_participant=has_properties(
                    user_uuid=UUID(answer_member_uuid),
                ),
            ),
        )
